  reqs:[{ id:"kycchange", to:"kyc", cat:"KYC", label:"Check for changes to the customer record",
      resp:"Registered address changed from Rotterdam to Tbilisi in January 2025. Telephone number changed the same week. The customer completed the change online; no re-verification of the new address was performed and the risk rating was not reassessed despite a change of residence to a jurisdiction the institution rates as higher risk." },
    { id:"orderers", to:"corr", cat:"Correspondent", label:"Identify the ordering parties",
      resp:"Three of the five ordering parties are trading companies incorporated within the last two years. One is a shipping agency with a verifiable trading history that has previously paid crew wages. One cannot be identified beyond the name on the message. Payment references read 'contract settlement' in four cases." }],
